export const grantable=["catalog","stock","count","count_create","transfer","purchase","sales","contacts","reports","reminders","stock_receive","stock_issue","stock_release","sales_order","sales_reserve","sales_pick","sales_pack","sales_dispatch","sales_return","sales_cancel","purchase_order","purchase_receive","purchase_return","purchase_cancel","approve_purchase","approve_transfer","approve_count"];
const id=()=>crypto.randomUUID(),r=n=>Math.round(n*1e6)/1e6,fail=s=>{throw Error(s)};
const positive=v=>{let n=Number(v);if(!Number.isFinite(n)||n<=0||n>1e9)fail('Invalid quantity');return r(n)};
const clean=(v,max=500)=>String(v??'').trim().slice(0,max);
const canonical=v=>Array.isArray(v)?v.map(canonical):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k])])):v;
export function upgrade(s){s=structuredClone(s);for(let k of ['reorderRules','supplierReturns','savedReports','purchaseRequests','qualityInspections','customRoles','automationRules','reportSchedules','transferRequests','exchangeRates','supplierQuotes'])s[k]||=[];for(let col of ['products','categories','brands','units','contacts','locations','reorderRules'])for(let row of s[col])row._revision??=0;for(let p of s.products){p.description||='';p.image||='';p.group||='';p.attributes||={};p.conversions||=[]}for(let b of s.stock){let p=s.products.find(p=>p.id===b.product);b.unitCost??=p?.price||0;b.costCurrency||=p?.currency||'IRR';b.costBasis||='reference'}for(let l of s.locations){l.parent||='';l.kind||='bin'}return s}
export const extensionTypes=['reorder_rule','location','location_update','bin_move','supplier_return','unit_conversion','saved_report','saved_report_delete','bulk_products','variants_generate','category_parent','location_capacity','purchase_request','purchase_request_approve','quality_inspect','count_recount','custom_role','automation_rule','report_schedule','transfer_request','transfer_policy','exchange_rate','supplier_quote','purchase_request_reject','transfer_request_reject','automation_toggle','report_schedule_toggle'];
export function metadata(p,a){p.description=clean(a.description??p.description,4000);p.group=clean(a.group??p.group,100);let attrs=a.attributes??p.attributes??{};if(typeof attrs!=='object'||Array.isArray(attrs)||Object.keys(attrs).length>20)fail('Invalid custom fields');p.attributes=Object.fromEntries(Object.entries(attrs).map(([k,v])=>[clean(k,60),clean(v,200)]));if(a.image!==undefined){if(a.image&&(!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(a.image)||a.image.length>900000))fail('Image must be PNG/JPEG/WebP under 650 KB');p.image=a.image}return p}
export function convert(s,a){a=structuredClone(a);const one=(product,q,unit)=>{let p=s.products.find(p=>p.id===product);if(!p)return q;if(!unit||unit===p.unit)return q;let c=p.conversions.find(c=>c.unit===unit);if(!c)fail('Unit conversion not defined');return r(positive(q)*c.factor)};if(['receive','issue','transfer'].includes(a.type)){let p=a.product;a.originalQty=a.qty;a.originalUnit=a.unit||s.products.find(p=>p.id===a.product)?.unit;a.qty=one(p,a.qty,a.unit)}if(a.type==='receive'&&a.unitCost!==undefined&&a.unit&&a.unit!==s.products.find(p=>p.id===a.product)?.unit){let p=s.products.find(p=>p.id===a.product),c=p.conversions.find(c=>c.unit===a.unit);a.unitCost=Number(a.unitCost)/c.factor}if(a.type==='order')a.lines=(a.lines||[]).map(l=>({...l,qty:one(l.product,l.qty,l.unit)}));return a}
export function applyExtension(original,a,actor){let s=upgrade(original),now=new Date().toISOString(),key=id(),signature=JSON.stringify(canonical(Object.fromEntries(Object.entries(a).filter(([k])=>k!=='requestId'))));if(a.requestId){let old=s.requests.find(x=>x.id===a.requestId);if(old){if(old.actor!==actor||old.signature!==signature)fail('Idempotency key conflict');return s}}
const product=()=>s.products.find(p=>p.id===a.product)||fail('Unknown product'),warehouse=w=>s.warehouses.find(x=>x.id===w)||fail('Unknown warehouse');
const movement=(b,qty,type)=>s.movements.unshift({id:id(),product:b.product,warehouse:b.warehouse,location:b.location,lot:b.lot,serial:b.serial,qty,at:now,type,ref:key});
switch(a.type){
case 'location':case 'location_update':{warehouse(a.warehouse);let old=a.id?s.locations.find(l=>l.id===a.id):null;if(a.type==='location_update'&&!old)fail('Location not found');if(!clean(a.name))fail('Location name required');if(!['zone','aisle','rack','shelf','bin'].includes(a.kind||'bin'))fail('Invalid location type');if(a.parent&&!s.locations.some(l=>l.id===a.parent&&l.warehouse===a.warehouse))fail('Parent location belongs to another warehouse');let parent=a.parent,seen=new Set([old?.id]);while(parent){if(seen.has(parent))fail('Location hierarchy cycle');seen.add(parent);parent=s.locations.find(l=>l.id===parent)?.parent}if(old&&old.warehouse!==a.warehouse)fail('Cannot change location warehouse');let row={id:old?.id||key,warehouse:a.warehouse,name:clean(a.name,100),en:clean(a.en||a.name,100),parent:a.parent||'',kind:a.kind||'bin'};if(s.locations.some(l=>l.id!==row.id&&l.warehouse===row.warehouse&&l.parent===row.parent&&l.name===row.name))fail('Duplicate location');if(old)Object.assign(old,row);else s.locations.push(row);break}
case 'bin_move':{let b=s.stock.find(b=>b.id===a.layer)||fail('Layer not found'),n=positive(a.qty);if(n>r(b.qty-b.reserved))fail('Insufficient available, unexpired stock');if(b.serial&&n!==1)fail('Serial quantity must be whole');if(a.location===b.location||!s.locations.some(l=>l.id===a.location&&l.warehouse===b.warehouse))fail('Choose another location in the same warehouse');b.qty=r(b.qty-n);movement(b,-n,'relocate_out');let dest={...b,id:id(),location:a.location,qty:n,reserved:0};s.stock.push(dest);movement(dest,n,'relocate_in');break}
case 'supplier_return':{let b=s.stock.find(b=>b.id===a.layer)||fail('Layer not found'),n=positive(a.qty);if(n>r(b.qty-b.reserved))fail('Return exceeds unreserved stock');if(b.serial&&n!==1)fail('Serial quantity must be whole');if(!s.contacts.some(c=>c.id===a.supplier&&c.type==='supplier')||!clean(a.reason))fail('Supplier and return reason required');b.qty=r(b.qty-n);movement(b,-n,'supplier_return');s.supplierReturns.unshift({id:key,product:b.product,warehouse:b.warehouse,layer:b.id,qty:n,supplier:a.supplier,reason:clean(a.reason,1000),at:now});break}
case 'unit_conversion':{let p=product(),factor=positive(a.factor);if(a.unit===p.unit||!s.units.some(u=>u.code===a.unit))fail('Choose a different valid unit');let c=p.conversions.find(c=>c.unit===a.unit);if(c)c.factor=factor;else p.conversions.push({unit:a.unit,factor});break}
case 'reorder_rule':{let p=product();warehouse(a.warehouse);const min=Number(a.min),target=Number(a.target),safety=Number(a.safety||0),leadDays=Number(a.leadDays||0);if(![min,target,safety,leadDays].every(n=>Number.isFinite(n)&&n>=0&&n<=1e9)||target<min)fail('Target must be at least the reorder point');if(a.supplier&&!s.contacts.some(c=>c.id===a.supplier&&c.type==='supplier'))fail('Unknown supplier');let row={id:key,product:p.id,warehouse:a.warehouse,min,target,safety,leadDays,supplier:a.supplier||''},old=s.reorderRules.find(x=>x.product===p.id&&x.warehouse===a.warehouse);if(old)Object.assign(old,{...row,id:old.id});else s.reorderRules.push(row);break}
case 'saved_report':{if(!clean(a.name))fail('Name required');let filters=a.filters||{};s.savedReports.unshift({id:key,actor,name:clean(a.name,100),filters:{search:clean(filters.search),warehouse:clean(filters.warehouse),from:clean(filters.from),to:clean(filters.to),report:['summary','movement','aging','dead','performance'].includes(filters.report)?filters.report:'summary'}});break}
case 'saved_report_delete':{let row=s.savedReports.find(x=>x.id===a.id&&x.actor===actor)||fail('Saved report not found');s.savedReports=s.savedReports.filter(x=>x!==row);break}

case 'category_parent':{let c=s.categories.find(c=>c.id===a.id)||fail('Record not found');if(a.parent&&!s.categories.some(c=>c.id===a.parent))fail('Invalid parent category');let seen=new Set([c.id]),parent=a.parent;while(parent){if(seen.has(parent))fail('Category hierarchy cycle');seen.add(parent);parent=s.categories.find(c=>c.id===parent)?.parent}c.parent=a.parent||'';break}
case 'location_capacity':{let l=s.locations.find(l=>l.id===a.id)||fail('Location not found'),capacity=Number(a.capacity);if(!Number.isInteger(capacity)||capacity<0||capacity>100000)fail('Invalid capacity');let used=new Set(s.stock.filter(b=>b.location===l.id&&b.qty>0).map(b=>b.product)).size;if(capacity&&used>capacity)fail('Capacity below occupied SKUs');l.capacity=capacity;break}
case 'bulk_products':{if(!Array.isArray(a.skus)||!a.skus.length||a.skus.length>500||new Set(a.skus).size!==a.skus.length)fail('Enter 1–500 unique SKUs');if(!['min','target','price','category','brand'].includes(a.field))fail('Invalid bulk field');let value=['min','target','price'].includes(a.field)?Number(a.value):clean(a.value);if(typeof value==='number'&&(!Number.isFinite(value)||value<0||value>1e12))fail('Invalid bulk value');if(a.field==='category'&&!s.categories.some(x=>x.id===value))fail('Unknown category');if(a.field==='brand'&&!s.brands.some(x=>x.id===value))fail('Unknown brand');for(let sku of a.skus){let p=s.products.find(p=>p.sku===sku)||fail('Unknown SKU: '+sku);p[a.field]=value;if(p.target<p.min)fail('Target must be at least the reorder point')}break}
case 'variants_generate':{let p=product(),dimensions=a.dimensions||{[clean(a.variantAttribute,60)]:a.values};if(typeof dimensions!=='object'||Array.isArray(dimensions)||!Object.keys(dimensions).length||Object.keys(dimensions).length>5)fail('Enter 1–5 variant attributes');let combinations=[{}];for(let [attribute,raw] of Object.entries(dimensions)){attribute=clean(attribute,60);if(!attribute||!Array.isArray(raw)||!raw.length||raw.length>50)fail('Enter an attribute and 1–50 values');let values=raw.map(v=>clean(v,100));if(values.some(v=>!v)||new Set(values).size!==values.length)fail('Duplicate or empty variant values');if(combinations.length*values.length>200)fail('Maximum 200 variant combinations');combinations=combinations.flatMap(c=>values.map(value=>({...c,[attribute]:value})))}let group=p.group||p.sku;p.group=group;for(let [i,attrs] of combinations.entries()){let sku=p.sku+'-V'+String(i+1).padStart(2,'0');if(s.products.some(x=>x.sku===sku))fail('Variant SKU already exists');let suffix=Object.values(attrs).join(' / ');s.products.push({...structuredClone(p),id:id(),sku,name:p.name+' / '+suffix,en:p.en+' / '+suffix,barcode:'',group,attributes:{...p.attributes,...attrs}})}break}
case 'purchase_request':{warehouse(a.warehouse);let p=product(),qty=positive(a.qty);if(!clean(a.name))fail('Name required');s.purchaseRequests.unshift({id:key,name:clean(a.name),warehouse:a.warehouse,product:p.id,qty,note:clean(a.note,1000),status:'pending',actor,at:now});break}
case 'purchase_request_approve':{let req=s.purchaseRequests.find(r=>r.id===a.id)||fail('Request not found');if(req.status!=='pending')fail('Request already processed');if(req.actor===actor)fail('Requester cannot approve their own request');req.status='approved';req.approvedBy=actor;req.approvedAt=now;break}
case 'quality_inspect':{let b=s.stock.find(b=>b.id===a.layer)||fail('Layer not found');if(b.status!=='quarantine')fail('Stock is not quarantined');if(!['available','damaged'].includes(a.decision)||!clean(a.reason))fail('Inspection decision and reason required');if(a.decision==='available'&&!['packagingOk','productOk','identityOk'].every(k=>a.checks?.[k]===true))fail('All quality checks must pass before release');b.status=a.decision;s.qualityInspections.unshift({id:key,layer:b.id,warehouse:b.warehouse,checks:a.checks||{},decision:a.decision,reason:clean(a.reason),actor,at:now});break}
case 'count_recount':{let c=s.counts.find(c=>c.id===a.id)||fail('Count not found');if(c.status!=='pending')fail('Count already approved');if(c.createdBy===actor)fail('Recount requires a different operator');if(!Array.isArray(a.lines)||a.lines.length!==c.lines.length)fail('Recount all original layers');let seen=new Set();c.recount={actor,at:now,lines:a.lines.map(x=>{let old=c.lines.find(l=>l.layer===x.layer);if(!old||seen.has(x.layer))fail('Invalid recount layer');seen.add(x.layer);let q=Number(x.qty);if(!Number.isFinite(q)||q<0||q>1e9)fail('Invalid counted quantity');return {layer:x.layer,qty:q}})};for(let l of c.lines)l.counted=c.recount.lines.find(x=>x.layer===l.layer).qty;break}


case 'custom_role':{let permissions=Array.isArray(a.permissions)?[...new Set(a.permissions)]:[];if(!clean(a.name)||!permissions.length||permissions.some(p=>!grantable.includes(p)))fail('Invalid custom role permissions');let row={id:a.id||'role-'+key,name:clean(a.name,100),permissions},old=s.customRoles.find(r=>r.id===row.id);if(old)Object.assign(old,row);else s.customRoles.push(row);break}
case 'automation_rule':{if(!clean(a.name)||!['low','expiry'].includes(a.trigger))fail('Invalid automation rule');let days=Number(a.days||30);if(!Number.isInteger(days)||days<1||days>365)fail('Days must be 1–365');s.automationRules.push({id:key,name:clean(a.name),trigger:a.trigger,days,actor,active:true});break}
case 'report_schedule':{if(!clean(a.name))fail('Name required');s.reportSchedules.push({id:key,name:clean(a.name),actor,active:true,lastRun:'',createdAt:now});break}

case 'transfer_policy':{s.settings.transferApprovalRequired=a.enabled===true;break}
case 'transfer_request':{product();warehouse(a.from);warehouse(a.to);if(a.from===a.to)fail('Destination must differ');let qty=positive(a.qty);if(a.location&&!s.locations.some(l=>l.id===a.location&&l.warehouse===a.from))fail('Location belongs to another warehouse');s.transferRequests.unshift({id:key,from:a.from,to:a.to,product:a.product,qty,location:a.location||'',serial:clean(a.serial),status:'pending',actor,at:now});break}

case 'exchange_rate':{let rate=positive(a.rate),currencies=['IRR','IRT','USD','EUR','AED','GBP'];if(!currencies.includes(a.fromCurrency)||!currencies.includes(a.toCurrency)||a.fromCurrency===a.toCurrency)fail('Choose two different currencies');s.exchangeRates.unshift({id:key,from:a.fromCurrency,to:a.toCurrency,rate,at:now,actor});break}

case 'supplier_quote':{let p=product();if(!s.contacts.some(c=>c.id===a.supplier&&c.type==='supplier'))fail('Unknown supplier');let price=Number(a.price),minQty=positive(a.minQty||1),leadDays=Number(a.leadDays||0);if(!Number.isFinite(price)||price<0||price>1e12||!Number.isInteger(leadDays)||leadDays<0||leadDays>3650||!['IRR','IRT','USD','EUR','AED','GBP'].includes(a.currency))fail('Invalid supplier quote');if(a.validUntil&&(!/^\d{4}-\d{2}-\d{2}$/.test(a.validUntil)||!Number.isFinite(Date.parse(a.validUntil))))fail('Invalid quote expiry');s.supplierQuotes.unshift({id:key,product:p.id,supplier:a.supplier,price,currency:a.currency,minQty,leadDays,validUntil:a.validUntil||'',at:now,actor});break}

case 'purchase_request_reject':case 'transfer_request_reject':{let rows=a.type==='purchase_request_reject'?s.purchaseRequests:s.transferRequests,req=rows.find(r=>r.id===a.id)||fail('Request not found');if(req.status!=='pending'||!clean(a.reason))fail('Pending request and reason required');req.status='rejected';req.rejectedBy=actor;req.reason=clean(a.reason,1000);req.rejectedAt=now;break}
case 'automation_toggle':{let row=s.automationRules.find(r=>r.id===a.id)||fail('Rule not found');row.active=a.active===true;break}
case 'report_schedule_toggle':{let row=s.reportSchedules.find(r=>r.id===a.id&&r.actor===actor)||fail('Report schedule not found');row.active=a.active===true;break}
default:fail('Unsupported action');
}
s.revision++;s.audit.unshift({id:key,actor,action:a.type,at:now,reason:clean(a.reason,1000),detail:a});if(a.requestId)s.requests.push({id:a.requestId,actor,signature});return s;
}
export function validateExtensions(s){for(let role of s.customRoles)if(!/^role-[a-zA-Z0-9-]+$/.test(role.id)||!role.name||!Array.isArray(role.permissions)||!role.permissions.length||role.permissions.some(p=>!grantable.includes(p)))fail('Invalid custom role permissions');if(new Set(s.customRoles.map(r=>r.id)).size!==s.customRoles.length)fail('Duplicate custom role');for(let req of s.transferRequests)if(!s.warehouses.some(w=>w.id===req.from)||!s.warehouses.some(w=>w.id===req.to)||req.from===req.to||!s.products.some(p=>p.id===req.product)||!Number.isFinite(req.qty)||req.qty<=0)fail('Invalid transfer request');for(let quote of s.supplierQuotes)if(!s.products.some(p=>p.id===quote.product)||!s.contacts.some(c=>c.id===quote.supplier&&c.type==='supplier')||!Number.isFinite(quote.price)||quote.price<0||!Number.isFinite(quote.minQty)||quote.minQty<=0)fail('Invalid supplier quote');for(let b of s.stock)if(!Number.isFinite(b.unitCost)||b.unitCost<0||b.unitCost>1e12||!['IRR','IRT','USD','EUR','AED','GBP'].includes(b.costCurrency))fail('Invalid stock cost');for(let r of s.exchangeRates)if(!Number.isFinite(r.rate)||r.rate<=0)fail('Invalid exchange rate');for(let c of s.categories){let seen=new Set([c.id]),parent=c.parent;while(parent){if(seen.has(parent))fail('Category hierarchy cycle');seen.add(parent);let row=s.categories.find(x=>x.id===parent);if(!row)fail('Invalid parent category');parent=row.parent}}for(let l of s.locations){let used=new Set(s.stock.filter(b=>b.location===l.id&&b.qty>0).map(b=>b.product)).size;if(l.capacity&&used>l.capacity)fail('Location capacity exceeded')}for(let req of s.purchaseRequests)if(!s.warehouses.some(w=>w.id===req.warehouse)||!s.products.some(p=>p.id===req.product)||!Number.isFinite(req.qty)||req.qty<=0)fail('Invalid purchase request');for(let rule of s.reorderRules)if(!s.products.some(p=>p.id===rule.product)||!s.warehouses.some(w=>w.id===rule.warehouse)||rule.target<rule.min)fail('Invalid reorder rule');for(let l of s.locations){let seen=new Set([l.id]),parent=l.parent;while(parent){if(seen.has(parent))fail('Location hierarchy cycle');seen.add(parent);let row=s.locations.find(x=>x.id===parent&&x.warehouse===l.warehouse);if(!row)fail('Invalid parent location');parent=row.parent}}for(let p of s.products)for(let c of p.conversions)if(!s.units.some(u=>u.code===c.unit)||!Number.isFinite(c.factor)||c.factor<=0)fail('Invalid unit conversion');return s}
